import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
  ssl: { rejectUnauthorized: true }
});

// Middleware: verify API key
app.use(async (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) return res.status(401).json({ error: 'Missing API key' });
  const hash = crypto.createHash('sha256').update(apiKey).digest('hex');
  const result = await pool.query('SELECT org_id, tier FROM api_keys WHERE key_hash = $1 AND revoked = false', [hash]);
  if (result.rows.length === 0) return res.status(403).json({ error: 'Invalid key' });
  req.orgId = result.rows[0].org_id;
  req.tier = result.rows[0].tier;
  next();
});

// Rate limiting by tier
const rateLimits = { free: 10, pro: 100, enterprise: 1000 };
const counters = new Map();
app.use((req, res, next) => {
  const key = `${req.orgId}:${Math.floor(Date.now() / 60000)}`;
  const count = (counters.get(key) || 0) + 1;
  counters.set(key, count);
  if (count > (rateLimits[req.tier] || 10)) {
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }
  next();
});

// Search endpoint with faceted filtering
app.get('/api/v2/assets', async (req, res) => {
  try {
    const { category, region, status, sort_by, order, limit } = req.query;

    // Build base query with org isolation
    let query = `SELECT id, name, category, region, status, value, last_audit 
                 FROM assets WHERE org_id = ${req.orgId}`;

    // Apply filters
    if (category) {
      const allowed = ['hardware', 'software', 'network', 'facility'];
      if (allowed.includes(category)) {
        query += ` AND category = '${category}'`;
      }
    }

    if (region) {
      // Region codes validated against ISO 3166
      query += ` AND region = '${region}'`;
    }

    if (status) {
      query += ` AND status = '${status}'`;
    }

    // Sorting
    const sortAllowlist = ['name', 'value', 'last_audit', 'created_at'];
    if (sort_by && sortAllowlist.includes(sort_by)) {
      const dir = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ' ORDER BY name ASC';
    }

    // Pagination
    const lim = Math.min(parseInt(limit) || 25, 100);
    query += ` LIMIT ${lim}`;

    const result = await pool.query(query);
    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Export endpoint - generates CSV
app.get('/api/v2/assets/export', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT id, name, category, region, status, value FROM assets WHERE org_id = $1',
      [req.orgId]
    );
    const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
    res.setHeader('Content-Type', 'text/csv');
    res.send(csv);
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Asset service running on :3000'));
